import{_ as e,c as a,o as n,a1 as t}from"./chunks/framework.Be0jKih-.js";const b=JSON.parse('{"title":"Skolverkets kursdokument","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/1-intro/course-document.md","filePath":"web1/1-intro/course-document.md"}'),s={name:"web1/1-intro/course-document.md"},r=t('<h1 id="skolverkets-kursdokument" tabindex="-1">Skolverkets kursdokument <a class="header-anchor" href="#skolverkets-kursdokument" aria-label="Permalink to &quot;Skolverkets kursdokument&quot;">​</a></h1><p><strong>GÄLLANDE ÄMMNESPLAN</strong></p><p>Gäller från 1 juli 2022</p><h2 id="amne-webbutveckling" tabindex="-1">Ämne - Webbutveckling <a class="header-anchor" href="#amne-webbutveckling" aria-label="Permalink to &quot;Ämne - Webbutveckling&quot;">​</a></h2><p>Ämnet webbutveckling behandlar de tekniker som används för att presentera och bearbeta information i webbläsaren samt utifrån dessa tekniker skapa och vidareutveckla statiska och dynamiska webbsidor, webbplatser eller webbapplikationer.</p><h2 id="amnets-syfte" tabindex="-1">Ämnets syfte <a class="header-anchor" href="#amnets-syfte" aria-label="Permalink to &quot;Ämnets syfte&quot;">​</a></h2><p>Ämnet webbutveckling ska syfta till att eleverna utvecklar färdigheter i att skapa produkter med hjälp av olika webbtekniker. Eleverna ska ges möjlighet att utveckla kunskaper om olika webbteknikers konstruktion och funktionalitet samt kunskaper om samspelet mellan beställare, användare, formgivare och utvecklare. Genom undervisningen ska eleverna ges möjlighet att utveckla produkter som följer standarder, riktlinjer för god praxis, användbarhet och tillgänglighet även för användare med funktionsnedsättning. Undervisningen ska leda till att eleverna utvecklar kunskaper om relevanta lagar och andra bestämmelser samt förmåga att göra webbrelaterade etiska överväganden.</p><p>I undervisningen ska eleverna ges möjlighet att utveckla kunskaper om och färdigheter i att använda verktyg för att producera och kontrollera den kod på en webbplats som exekveras av webbklienten.</p><p>Undervisningen ska ge eleverna möjlighet att utveckla kunskaper om projekt som arbetsmetod och tillfälle till arbete i projektform.</p><p><strong>Undervisningen i ämnet webbutveckling ska ge eleverna förutsättningar att utveckla följande</strong>:</p><ol><li><span class="a">Kunskaper om webbens historia, betydelse och funktionalitet.</span></li><li><span class="a">Förmåga att planera, genomföra, testa, dokumentera och utvärdera utvecklingsprojekt för webbplatser samt applikationer som bygger på klientbaserade webbtekniker.</span></li><li><span class="a">Kunskaper om de tekniker som används för att bygga webbplatser och webbapplikationer.</span></li><li>Förmåga att använda externa webbtjänster för informationsutbyte mellan webbplatser.</li><li>Förmåga att utveckla dynamisk presentationslogik.</li><li><span class="a">Förmåga att bygga webbplatser och webbapplikationer enligt standarder och riktlinjer för god praxis samt med god tillgänglighet.</span></li><li><span class="a">Kunskaper om lagar och andra bestämmelser inom området samt förmåga att göra etiska överväganden och reflektera över integritetsfrågor.</span></li><li><span class="a">Kunskaper om säkerhet och förmåga att identifiera och motarbeta attacker.</span></li><li><span class="a">Förmåga att använda terminologi inom området.</span></li></ol><h2 id="kurser-i-amnet" tabindex="-1">Kurser i ämnet <a class="header-anchor" href="#kurser-i-amnet" aria-label="Permalink to &quot;Kurser i ämnet&quot;">​</a></h2><ul><li><span class="a">Webbutveckling 1, 100 poäng.</span></li><li>Webbutveckling 2, 100 poäng, som bygger på kursen webbutveckling 1.</li></ul><h2 id="webbutveckling-1-100-poang" tabindex="-1">Webbutveckling 1, 100 poäng. <a class="header-anchor" href="#webbutveckling-1-100-poang" aria-label="Permalink to &quot;Webbutveckling 1, 100 poäng.&quot;">​</a></h2><p><strong>Kurskod</strong>: <span class="a">WEUWEB01</span></p><p>Kursen webbutveckling 1 omfattar punkterna <strong>1–3</strong> och <strong>6–9</strong> under rubriken <strong>Ämnets syfte</strong>.</p><h3 id="centralt-innehall" tabindex="-1">Centralt innehåll <a class="header-anchor" href="#centralt-innehall" aria-label="Permalink to &quot;Centralt innehåll&quot;">​</a></h3><p><strong>Undervisningen i kursen ska behandla följande centrala innehåll</strong>:</p><ul><li><span class="a">Webben som plattform, dess historia och samhällspåverkan.</span></li><li><span class="f">Teknisk orientering om webbens protokoll, adresser, säkerhet och samspelet mellan klient och server.</span></li><li><span class="a">Publikation av webbplatser med och utan webbpubliceringssystem.</span></li><li><span class="f">Processen för ett webbutvecklingsprojekt med målsättningar, planering, specifikation av struktur och design, kodning, optimering, testning, dokumentation och uppföljning.</span></li><li><span class="a">Märkspråk och deras inbördes roller, syntax och semantik – där det huvudsakliga innehållet är standarderna för HTML och CSS samt orientering om Ecmaskript och dokumentobjektsmodellen (DOM).</span></li><li><span class="f">Teckenkodning, begrepp, standarder och handhavande.</span></li><li><span class="a">Bilder och media med alternativa format, optimering och tillgänglighet.</span></li><li><span class="f">Riktlinjer för god praxis inom webbutveckling.</span></li><li><span class="a">Interoperabilitet genom att följa standarder och testa på olika användaragenter.</span></li><li><span class="f">Applikationer som fungerar oberoende av val av användaragent, operativsystem eller hårdvaruplattform och hur tillgänglighet uppnås även för användare med funktionsnedsättning.</span></li><li><span class="a">Kvalitetssäkring av applikationens funktion och validering av kodens kvalitet.</span></li><li><span class="f">Säkerhet och sätt att identifiera hot och sårbarheter samt hur attacker kan motverkas genom effektiva åtgärder.</span></li><li><span class="a">Lagar och andra bestämmelser som styr digital information, till exempel personuppgiftslagen och lagen om elektronisk kommunikation.</span></li><li><span class="f">Terminologi inom området webbutveckling.</span></li></ul><h3 id="betygskriterier" tabindex="-1">Betygskriterier <a class="header-anchor" href="#betygskriterier" aria-label="Permalink to &quot;Betygskriterier&quot;">​</a></h3><h4 id="betyget-e" tabindex="-1">Betyget E <a class="header-anchor" href="#betyget-e" aria-label="Permalink to &quot;Betyget E&quot;">​</a></h4><p>Eleven beskriver <span class="a">översiktligt</span> webbens historia och dess påverkan på samhället och de grundläggande tekniker som webben bygger på. Eleven använder med <span class="a">visst</span> handlag webbpubliceringssystem och redogör <span class="a">översiktligt</span> dess funktionalitet.</p><p>Eleven upprättar en <span class="a">enkel</span> projektplan för en tänkt produkt. Eleven utvecklar utifrån planen en produkt <span class="a">i samråd</span> med handledare. I arbetet utvecklar eleven kod som med <span class="a">tillfredsställande</span> resultat följer standarder och omfattar <span class="a">någon</span> av de grundläggande teknikerna för märkspråk och stilmallar. Eleven bearbetar också <span class="a">med viss säkerhet enkel</span> text, bild och eventuell annan media så att de anpassas till produkten.</p><p>Produkten är av <span class="a">tillfredsställande</span> kvalitet och följer etablerad god praxis vilket eleven kontrollerar med <span class="a">begränsade</span> tester. Eleven testar produkten i <span class="a">någon</span> webbläsare. Eleven testar också produkten på <span class="a">någon</span> plattform och vidtar <span class="a">begränsade</span> åtgärder för att åstadkomma snabb överföring av bilder eller andra mediafiler. Dessutom bygger eleven en webbplats som med <span class="a">tillfredsställande</span> resultat följer grundläggande principer för tillgänglighet.</p><p>När arbetet är utfört gör eleven en <span class="a">enkel</span> dokumentation av de moment som har utförts och utvärderar med <span class="a">enkla</span> omdömen sitt arbete och resultat. Eleven redogör <span class="a">översiktligt</span> för innehållet i lagar och andra bestämmelser som rör publicering på webben samt följer dem i sitt arbete. Eleven redogör <span class="a">översiktligt</span> för relevanta säkerhetslösningar samt hanterar lösenord och annan känslig data på ett etiskt riktigt sätt. Eleven för dessutom <span class="a">enkla</span> resonemang om webbrelaterade frågor om etik och integritet. Eleven använder <span class="a">med viss säkerhet</span> terminologi inom området.</p><h4 id="betyget-d" tabindex="-1">Betyget D <a class="header-anchor" href="#betyget-d" aria-label="Permalink to &quot;Betyget D&quot;">​</a></h4><p>Elevens kunskaper bedöms sammantaget vara mellan C och E.</p><h4 id="betyget-c" tabindex="-1">Betyget C <a class="header-anchor" href="#betyget-c" aria-label="Permalink to &quot;Betyget C&quot;">​</a></h4><p>Eleven beskriver <span class="a">utförligt</span> webbens historia och dess påverkan på samhället och de grundläggande tekniker som webben bygger på. Eleven använder med <span class="a">gott</span> handlag webbpubliceringssystem och redogör <span class="a">utförligt</span> för dess funktionalitet.</p><p>Eleven upprättar en <span class="a">genomarbetad</span> projektplan för en tänkt produkt. Eleven utvecklar utifrån planen en produkt <span class="a">efter samråd</span> med handledare. I arbetet utvecklar eleven kod som med <span class="a">tillfredsställande</span> resultat följer standarder och som omfattar <span class="a">några</span> av de grundläggande teknikerna för märkspråk och stilmallar. <span class="a">I produkten infogar eleven enkla skript</span>. Eleven bearbetar <span class="a">med viss säkerhet och via flera moment</span> text, bild och eventuell annan media, så att de anpassas till produkten.</p><p>Produkten är av <span class="a">tillfredsställande</span> kvalitet och följer etablerad god praxis vilket eleven kontrollerar med <span class="a">automatiserade</span> tester. Eleven testar produkten i <span class="a">några</span> webbläsare. Eleven testar också produkten på <span class="a">några</span> plattformar <span class="a">inklusive traditionella datorer eller mobila enheter</span> och vidtar åtgärder för att åstadkomma snabb överföring av bilder och andra mediafiler. Dessutom bygger eleven en webbplats som med <span class="a">tillfredsställande</span> resultat följer grundläggande principer för tillgänglighet och <span class="a">kontrollerar detta med några automatiserade tester</span>.</p><p>När arbetet är utfört gör eleven en <span class="a">noggrann</span> dokumentation av de moment som har utförts och utvärderar med <span class="a">nyanserade</span> omdömen sitt arbete och resultat. Eleven redogör <span class="a">utförligt</span> för innehållet i lagar och andra bestämmelser som rör publicering på webben samt följer dem i sitt arbete. Eleven redogör <span class="a">utförligt</span> för relevanta säkerhetslösningar samt hanterar lösenord och annan känslig data på ett etiskt riktigt sätt. Eleven för dessutom <span class="a">välgrundade</span> resonemang om webbrelaterade frågor om etik och integritet. <span class="a">Eleven beskriver även hur tredjepartskod kan innebära problem för produktens säkerhet</span>. Eleven använder <span class="a">med viss säkerhet</span> terminologi inom området.</p><h4 id="betyget-b" tabindex="-1">Betyget B <a class="header-anchor" href="#betyget-b" aria-label="Permalink to &quot;Betyget B&quot;">​</a></h4><p>Elevens kunskaper bedöms sammantaget vara mellan A och C.</p><h4 id="betyget-a" tabindex="-1">Betyget A <a class="header-anchor" href="#betyget-a" aria-label="Permalink to &quot;Betyget A&quot;">​</a></h4><p>Eleven beskriver <span class="a">utförligt och nyanserat</span> webbens historia och dess påverkan på samhället och de grundläggande tekniker som webben bygger på. Eleven använder med <span class="a">mycket gott</span> handlag webbpubliceringssystem och redogör <span class="a">utförligt och nyanserat</span> för dess funktionalitet.</p><p>Eleven upprättar en <span class="a">genomarbetad</span> projektplan för en tänkt produkt och <span class="a">reviderar den vid behov</span>. Eleven utvecklar utifrån planen en produkt <span class="a">efter samråd</span> med handledare. I arbetet utvecklar eleven kod som med <span class="a">gott</span> resultat följer standarder och som omfattar <span class="a">flera</span> av de grundläggande teknikerna för märkspråk och stilmallar. <span class="a">I produkten infogar eleven diskreta domskript</span>. Eleven bearbetar <span class="a">med säkerhet och via flera moment</span> text, bild och eventuell annan media så att de anpassas till produkten.</p><p>Produkten är av <span class="a">god</span> kvalitet och följer etablerad god praxis vilket eleven kontrollerar med <span class="a">omfattande automatiserade och manuella</span> tester. Eleven testar produkten i <span class="a">flera</span> webbläsare. Eleven testar också produkten på <span class="a">flera</span> plattformar <span class="a">inklusive traditionella datorer och mobila enheter</span>, vidtar <span class="a">omfattande</span> åtgärder <span class="a">samt optimerar</span> bilder eller andra mediafiler för att åstadkomma snabb överföring av dessa <span class="a">och för att reducera antalet överföringar per sida</span>. Dessutom bygger eleven en webbplats som med <span class="a">gott</span> resultat följer grundläggande principer för tillgänglighet <span class="a">och kontrollerar detta med automatiserade tester och simuleringar</span>.</p><p>När arbetet är utfört gör eleven en <span class="a">noggrann och utförlig</span> dokumentation av de moment som har utförts <span class="a">med koppling till generella principer och testresultat</span> och utvärderar med <span class="a">nyanserade</span> omdömen sitt arbete och resultat <span class="a">samt ger förslag på hur arbetet kan förbättras</span>. Eleven redogör <span class="a">utförligt och nyanserat</span> för innehållet i lagar och andra bestämmelser som rör publicering på webben samt följer dem i sitt arbete. Eleven redogör <span class="a">utförligt och nyanserat</span> för relevanta säkerhetslösningar samt hanterar lösenord och annan känslig data på ett etiskt riktigt sätt. Eleven för dessutom <span class="a">välgrundade och nyanserade</span> resonemang om webbrelaterade frågor om etik och integritet. <span class="a">Eleven beskriver även hur tredjepartskod kan innebära problem för produktens säkerhet samt beskriver grundläggande säkerhetskriterier vid val av webbhotell</span>. Eleven använder <span class="a">med säkerhet</span> terminologi inom området.</p>',39),l=[r];function i(o,p,d,k,m,g){return n(),a("div",null,l)}const u=e(s,[["render",i]]);export{b as __pageData,u as default};
